// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        vm.deal(actor, 0.1 ether);
        vm.prank(actor);
        address(c).call{value: 0.1 ether}("");

        uint256 countBefore = c.depositsCount();
        uint256 ownerBalBefore = c.owner().balance;
        uint256 balanceBefore = address(c).balance;

        vm.prank(actor);
        try c.withdrawAll() {
        } catch {}

        uint256 countAfter = c.depositsCount();
        uint256 balanceAfter = address(c).balance;
        uint256 ownerBalAfter = c.owner().balance;

        if (actor == c.owner()) {
            assertTrue(
                (countAfter == countBefore) &&
                (balanceAfter == 0) &&
                (ownerBalAfter >= ownerBalBefore + balanceBefore)
            );
        } else {
            assertTrue(
                (countAfter == countBefore) &&
                (balanceAfter == balanceBefore)
            );
        }
    }
}
